def count_no_of_ways(n, k):
    # Initialize a 2D list to store the number of ways to paint the fence
    dp = [[0] * k for _ in range(n)]

    # Base case: there's one way to paint a fence with 0 posts
    for i in range(n):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, n):
        for j in range(1, k):
            # If the current post has the same color as the previous post
            if i > 0 and dp[i-1][j] == 1:
                dp[i][j] = (dp[i-1][j] + dp[i-1][j-1]) % k

    # The number of ways to paint the fence is the sum of ways to paint the fence with 1 post and 2 posts
    return sum(dp[n-1])

